const tabId = 730410078;
const containerInfo = await browserjs(tabId, () => {
  const h3 = Array.from(document.querySelectorAll('h3')).find(h => h.innerText.includes('Trends'));
  let curr = h3;
  let ancestors = [];
  while (curr && curr !== document.body) {
    ancestors.push({
      tag: curr.tagName,
      className: curr.className,
      id: curr.id
    });
    curr = curr.parentElement;
  }

  // Find all elements within the ancestor that has class containing "trend" or similar
  const trendBlock = h3.closest('[class*="Trend"]') || h3.parentElement.parentElement.parentElement;
  return {
    ancestors,
    trendBlockHTML: trendBlock ? trendBlock.outerHTML.slice(0, 4000) : null,
    trendBlockText: trendBlock ? trendBlock.innerText : null
  };
});
